  },

  methods: {
    async init() {
       const tableRows = this.record?.tables?.[0]?.rows ?? [];

      await this.fetchMasterDataForSupplierItems(tableRows);
      this.prepareTableData();
      
    },
    prepareTableData() {
      this.prepareTableRow();
      this.prepareTableErrors();
    },
    prepareTableRow(): void {
      const tableRows = this.record?.tables?.[0]?.rows ?? [];
      this.tableRows = [];
     
      this.prepareTableColumns();
      for (const row of tableRows) {
        this.oneQuoteToLine(row);
      }
    },

    prepareTableColumns() {
