          field: 'managed_price',
          align: 'left',
          label: this.$t('managed_price') || 'Managed Price',
          sortable: true,
          originalName: 'managed_price',
        },
      
        {
          name: 'unit_price',
          field: 'unit_price',
          align: 'left',
          label: this.$t('unit_price'),
          sortable: true,
          originalName: 'unit_price',
        },
        {
          name: 'last_price_paid',
          field: 'last_price_paid',
          align: 'left',
          label: this.$t('last_price_paid') || 'Last Price Paid',
          sortable: true,
          originalName: 'last_price_paid',
        },
        {
          name: 'managed_unit',
          field: 'managed_unit',
          align: 'left',
          label: this.$t('managed_unit'),
          sortable: true,
          originalName: 'unit_of_measure',
        },
        {
          name: 'unit',
          field: 'unit',
          align: 'left',
          label: this.$t('unit'),
          sortable: true,
          originalName: 'unit',
        },
        {
          name: 'quantity',
          field: 'quantity',
          align: 'left',
          label: this.$t('quantity'),
          sortable: true,
          originalName: 'quantity',
        },
        {
          name: 'item_number',
          field: 'item_number',
          align: 'left',
          label: this.$t('item_number'),
          sortable: true,
          originalName: 'item_number',
        },
       
        {
          name: 'cost_center',
          field: 'cost_center',
          align: 'left',
          label: this.$t('cost_center'),
          sortable: true,
          originalName: 'cost_center',
        },
        {
          name: 'facility',
          field: 'facility',
          align: 'left',
          label: this.$t('facility'),
          sortable: true,
          originalName: 'facility',
        },
        
        {
          name: 'warehouse',
          field: 'warehouse',
          align: 'left',
          label: this.$t('warehouse'),
          sortable: true,
          originalName: 'warehouse',
        },
        {
          name: 'delivery_date',
          field: 'delivery_date',
          align: 'left',
          label: this.$t('delivery_date'),
          sortable: true,
          originalName: 'delivery_date',
        },
        {
          name: 'last_price_paid_last_updated',
          field: 'last_price_paid_last_updated',
          align: 'left',
          label: this.$t('last_price_paid_last_updated'),
          sortable: true,
          originalName: 'last_price_paid_last_updated',
        },
        {
          name: 'requisition_number',
          field: 'requisition_number',
          align: 'left',
          label: this.$t('requisition_number'),
          sortable: true,
          originalName: 'REQUISITION_NUMBER',
        },
        {
          name: 'supplier_item_number',
          field: 'supplier_item_number',
          align: 'left',
