          field: 'supplier_id',
          align: 'left',
          label: this.$t('supplier_id'),
          sortable: true,
          originalName: 'supplier_id',
        },
        {
          name: 'supplier_item_desc',
          field: 'supplier_item_desc',
          align: 'left',
          label: this.$t('supplier_item_description'),
          sortable: true,
          originalName: 'supplier_item_desc',
        },
        {
          name: 'internal_notes',
          field: 'internal_notes',
          align: 'left',
          label: this.$t('internal_notes'),
          sortable: true,
          originalName: 'internal_notes',
        },
        {
          name: 'net_amount',
