    },
    getLineTableValue (row: any, field: string): string {
      const col = row?.columns?.find((col: any) => col.name === field);
       
      return col ? col.value : '';
    },
    oneQuoteToLine(row: any): void {
      const quoteApproval = (this.record?.quote_approval_data || []).find(
        (info: any) => info.table_line_id === row.id
      );

      const supplier_item_key = this.getLineTableValue(row,'SUPPLIER_ITEM_KEY');
      const supplierItemNumber = this.getLineTableValue(row,'SUPPLIER_ITEM_NUMBER');
      // const supplierData = this.record?.quote_supplier_data?.[supplierItemNumber];

      const supplierData = this.supplierPriceMasterData?.[supplier_item_key];

      const params = {
        id: supplierData?.id,
        managed_price: !supplierData ? this.getLineTableValue(row,'UNIT_PRICE') : (
          supplierData?.managed_price?.toString() ?? (
            typeof quoteApproval?.approval_info?.managed_price === 'string'
              ? quoteApproval.approval_info.managed_price
              : ''
          )
        ),

        unit_price: this.getLineTableValue(row,'UNIT_PRICE'),
        item_number: this.getLineTableValue(row,'ITEM_NUMBER') ,
        item_desc: supplierData?.item_desc ? supplierData.item_desc : this.getLineTableValue(row,'RUIZ_ITEM_DESCRIPTION'),
        cost_center: this.getLineTableValue(row,'DIMENSION3'),
        facility: this.getLineTableValue(row,'DIMENSION2'),
        unit: this.getLineTableValue(row,'UNIT'),
        warehouse: this.getLineTableValue(row,'WAREHOUSE'),
        quantity: this.getLineTableValue(row,'QUANTITY'),
        delivery_date: this.getLineTableValue(row,'DELIVERY_DATE'),
        last_price_paid_last_updated: supplierData?.last_price_paid_last_updated ? this.formatDateWithPattern(supplierData.last_price_paid_last_updated, this.defaultDataePattren) : '',
        requisition_number: this.getLineTableValue(row,'REQUISITION_NUMBER'),
        supplier_item_number: supplierItemNumber,
        managed_class: supplierData?.managed_class ? supplierData.managed_class : this.getLineTableValue(row,'SUPPLIER_TYPE'),
        supplier_item_desc: this.getLineTableValue(row,'DESCRIPTION'),
        supplier_name: supplierData?.supplier_name ? supplierData.supplier_name : this.getLineTableValue(row,'SUPPLIER_NAME'),
        ship_to_location: this.getLineTableValue(row,'SHIP_TO_LOCATION'),
        accounting_id: this.getLineTableValue(row,'DIMENSION1'),
        taxable: supplierData ? supplierData?.taxable : this.getLineTableValue(row,'TAXABLE'),
        ref1: supplierData?.ref1 ? supplierData.ref1 : this.getLineTableValue(row,'DIMENSION5'),
        ref2: supplierData?.ref2,
        last_price_paid: supplierData ? supplierData?.last_price?.toString() : this.getLineTableValue(row,'UNIT_PRICE'),
        supplier_id: !supplierData ? this.getLineTableValue(row,'SUPPLIER_ID') : supplierData.supplier_id,
        // Prefer the managed UOM the approval is actually about
        // (approval_info.managed_unit) over supplierPriceMasterData, which is
        // keyed by supplier_item_key and collides when several lines share a key
        // — showing one line's UOM for all of them and mis-exporting on reject.
        // Falls back to the master-data / document value when there is no
        // approval snapshot (e.g. a new item).
        managed_unit: quoteApproval?.approval_info?.managed_unit
          ? quoteApproval.approval_info.managed_unit
          : (supplierData?.unit_of_measure ? supplierData?.unit_of_measure : this.getLineTableValue(row,'UNIT')),
        internal_notes: this.getLineTableValue(row,'INTERNAL_NOTES'),
        supplier_item_key: supplier_item_key,
        start_date: supplierData?.start_date ? this.formatDateWithPattern(supplierData.start_date, this.defaultDataePattren) : '',
        end_date: supplierData?.end_date ? this.formatDateWithPattern(supplierData.end_date, this.defaultDataePattren) : '',
        net_amount: this.getLineTableValue(row,'NET_AMOUNT'),
      };

      this.createNewTableRow(row, params, quoteApproval);
    },

    createNewTableRow(row: any, params: any, data: any): void {
      let applyManagedPriceClass = '';
      let applyUnitPriceClass = '';
      let highLightManagedPriceClass = '';
      let highLightUnitPriceClass = '';
      let applyManagedUnitClass = '';
      let applyUnitClass = '';
      let highLightManagedClass = '';
      let highLightUnitClass = '';
      let showIcon = false;
      const approvalInfo = data?.approval_info;
      const recordStatus = this.record?.status;
      const second_approval = 'approved_pending_second_approval'
      if (recordStatus === second_approval && approvalInfo) {
        if (approvalInfo.approval_status === 'rejected') {
          highLightManagedPriceClass = 'highlight-orange';
        }

        if (approvalInfo.approval_status === 'approved') {
          highLightUnitPriceClass = 'highlight-orange';
        }

        if (approvalInfo.uom_approval_status === 'rejected') {
          highLightManagedClass = 'highlight-orange';
        }

        if (approvalInfo.uom_approval_status === 'approved') {
          highLightUnitClass = 'highlight-orange';
        }
      }

      // Approval styling applies to CONTRACT quotes only — MANAGED and
      // UNMANAGED are excluded.
      const nonApprovalManagedClasses = [
        this.quoteTypeUnmanaged,
        this.quoteTypeManaged,
      ];
      if (
        approvalInfo &&
        recordStatus !== second_approval &&
        params.managed_class &&
        !nonApprovalManagedClasses.includes(params.managed_class)
      ) {
        const { managedPriceClass, uomClass } = this.getStyleClassForNormalColumns(approvalInfo);

        // Apply based on their actual logic
        applyManagedPriceClass = managedPriceClass ? 'no-right-border-' + managedPriceClass : '';
        applyUnitPriceClass = managedPriceClass ? 'no-left-border-' + managedPriceClass : '';
        applyManagedUnitClass = uomClass ? 'no-right-border-' + uomClass : '';
        applyUnitClass = uomClass ? 'no-left-border-' + uomClass : '';
      }

      if (
        applyManagedPriceClass === this.colorOrange ||
        applyUnitPriceClass === this.colorOrange ||
        applyManagedUnitClass === this.colorOrange ||
        applyUnitClass === this.colorOrange 
