    preapreFormData(row: any, isUpdate: boolean) {
      this.resetForm();

      Object.keys(this.formData).forEach((key: string) => {
        const typedKey = key;

        if (typedKey === 'id') {
          this.formData[typedKey] = isUpdate ? row.id : crypto.randomUUID();
        } else if (typedKey === 'supplier_item_key') {
          this.formData[typedKey] = row.supplier_item_key;
        } else if (row[typedKey] && typeof row[typedKey] === 'object' && 'value' in row[typedKey]) {
          this.formData[typedKey] = row[typedKey].value || '';
        } else {
          this.formData[typedKey] = row[typedKey] || '';
        }
      });
      
      this.formData['taxable'] = this.formData['taxable'] ? true : false;
