    async updateMatrixLookup(type: string, row: any) {
      let sucess = true;
      try {
        
        if (!row?.id || !row?.supplier_id?.value) {
          notify.error('Missing required fields for update.');
          return;
        }

        const payload = {
          id: row.id,
          supplier_item_key: row.supplier_item_key,
          item_num: row?.item_number?.value,
          item_desc: row?.item_desc?.value,
          facility: row?.facility?.value,
          supplier_id: row?.supplier_id?.value,
          supplier_name: row?.supplier_name?.value,
          supplier_item_id: row?.supplier_item_number?.value,
          supplier_item_desc: row?.supplier_item_desc?.value,
          managed_price: row?.managed_price?.value,
          unit_of_measure: row?.unit?.value,
          start_date: row?.start_date?.value,
          end_date: row?.end_date?.value,
          managed_class: row?.managed_class?.value,
          cost_center: row?.cost_center?.value,
          account: row?.accounting_id?.value,
          taxable: row?.taxable?.value,
          ref1: row?.ref1?.value,
          ref2: row?.ref2?.value,
          last_price: type === 'rejected' ? row?.managed_price?.value : row?.unit_price?.value
        }

        const validation = this.validateFormData(payload);
        if (!validation.isValid) {
          notify.error(validation.error);
          return;
        }

        //Using Bulk Update Endpoint here as it will update the provided fields only and not remove the dates
        const response = await masterDataApiService.updateBulkRecord('supplier_item_price', [payload]);

        if (!response || response.success !== true) {
          throw response;
        }

        notify.success('Updated Record');
        // Save document to persist changes
        this.saveDocument(this.record.doc_id);
      } catch (err: any) {
        let error =  err.message ? { 'message' : err.message} : err  ;
        const msg = ApiExceptions.getErrorMessage(error);
        notify.error(msg);
        logError(err);
        sucess = false;
      } finally {
        return sucess;
      }
    },

    validateFormData(formData: Record<string, string | boolean>): { isValid: boolean; error: string } {
      const managed_class = formData.managed_class as string;

      // Define non-mandatory (optional) fields based on managed_class
      const optionalFields: string[] = ['ref1', 'ref2', 'taxable', 'last_price_paid_last_updated'];

      // For MANAGED and NONMANAGED, start_date and end_date are also optional
      if (managed_class !== 'CONTRACT') {
        optionalFields.push('start_date', 'end_date');
      }

      // Check all fields except optional ones
      for (const [field, value] of Object.entries(formData)) {
        // Skip if field is optional
        if (optionalFields.includes(field)) {
          continue;
        }

        // Check if mandatory field is empty
        if (!value) {
          const fieldLabel = field.replace(/_/g, ' ').toUpperCase();
          return {
            isValid: false,
            error: `${fieldLabel} is required for ${managed_class || 'this'} managed class`
          };
        }
      }

      return { isValid: true, error: '' };
    },

    async handleSave() {
      try {
        // Validate form data
        const validation = this.validateFormData(this.formData);
        if (!validation.isValid) {
          notify.error(validation.error);
          return;
        }

        const supplier_item_key = this.formData.supplier_item_key as string;

        const payload: any = {
          id: this.formData.id,
          item_num: this.formData.item_number,
          item_desc: this.formData.item_desc,
          facility: this.formData.facility,
          supplier_id: this.formData.supplier_id,
          supplier_name: this.formData.supplier_name,
          supplier_item_id: this.formData.supplier_item_number,
          supplier_item_desc: this.formData.supplier_item_desc,
          managed_price: this.formData.managed_price,
          unit_of_measure: this.formData.unit,
          start_date: this.formData.start_date,
          end_date: this.formData.end_date,
          managed_class: this.formData.managed_class,
          cost_center: this.formData.cost_center,
          account: this.formData.accounting_id,
          taxable: this.formData.taxable,
          ref1: this.formData.ref1,
          ref2: this.formData.ref2,
          last_price: this.formData.last_price_paid,
          supplier_item_key: supplier_item_key,
        }

        const supplierData = this.supplierPriceMasterData?.[supplier_item_key];

        if(!supplierData) {
          payload.last_price = payload.managed_price;
        }
        
        // if case is new record or Last Price Paid is updated, then update the date
        if(!supplierData || supplierData.last_price?.toString() !== this.formData.last_price_paid?.toString()) {
          payload['last_price_paid_last_updated'] = new Date().toISOString();
        } else {
          payload['last_price_paid_last_updated'] = supplierData.last_price_paid_last_updated
        }
        const response = await this.updateRow(
          'supplier_item_price',
          payload,
          !this.isUpdateMode,
          this.selectedRowIndex ?? 0
        );

        if (!response || response.success !== true) {
          throw response;
        }

        if (this.isUpdateMode) {
          // Update mode: Update existing attributes in supplierPriceMasterData
          if (this.supplierPriceMasterData[supplier_item_key]) {
            Object.assign(this.supplierPriceMasterData[supplier_item_key], payload);
          }
        } else {
          // Add mode: Push new item to supplierPriceMasterData
          this.supplierPriceMasterData[supplier_item_key] = payload;
        }

        // Refresh the entire table
        this.tableRows = [];
        this.prepareTableData();

        // If adding new record and managed_price differs from unit_price, mark as rejected
        if (!this.isUpdateMode) {
          const row = this.tableRows.find((r: any) => r.supplier_item_key === supplier_item_key);
          if (row) {
            const managedPrice = parseFloat(this.formData.managed_price as string) || 0;
            const unitPrice = parseFloat(row.unit_price?.value) || 0;

            if (managedPrice !== unitPrice) {
              // Update approval info directly (same as handleApprovalInfo for rejection)
              const quoteRecord = (this.record.quote_approval_data || []).find(
                (entry: any) => entry.table_line_id === row.row_id
              );

              if (quoteRecord && quoteRecord.approval_info) {
                quoteRecord.approval_info.approval_status = this.approvalInfoStatus.rejected;
                quoteRecord.approval_info.needs_approval = false;
                quoteRecord.approval_info.last_price_paid = row.managed_price.value;
                quoteRecord.approval_info.price_to_export = row.managed_price.value;
              }

              // Update row classes for visual indication
              row.unit_price.class = 'no-left-border-error';
              row.managed_price.class = 'no-right-border-error';

              // Update approval columns and error indicators
              this.handleRowApprovalStatus(row);
            }
          }
        }

       notify.success(this.isUpdateMode ? 'Updated Record' : 'Created Record');
        // Save document to persist changes
        this.saveDocument(this.record.doc_id);
        this.closeDialog();
      } catch (err: any) {
        const msg = ApiExceptions.getErrorMessage(err);
        notify.error(msg);
        logError(err);
      }
    },

