    saveNote() {
      if (!this.noteText.trim()) {
        // notify.error(this.$t('NOTE_REQUIRED') || 'Note is required');
        return;
      }

      // ✅ Bulk reject flow
      if (this.bulkRejectTarget?.rows?.length > 0) {
        for (const { row, quoteEntry } of this.bulkRejectTarget.rows) {
          if (quoteEntry && quoteEntry.approval_info) {
            quoteEntry.approval_info.notes = this.noteText;
          }

          this.proceedWithRejection(row, this.bulkRejectTarget.column);
        }

        this.bulkRejectTarget = { rows: [], column: '' };
        this.showNotesDialog = false;
        this.noteText = '';
        return;
      }

      // ✅ If not bulk, fallback to single cell note (optional)
      const { row, column } = this.noteTarget;
      const quoteEntry = (this.record.quote_approval_data || []).find(
        (entry: any) => entry.table_line_id === row?.row_id
      );

      if (quoteEntry && quoteEntry.approval_info) {
        quoteEntry.approval_info.notes = this.noteText;
      }

      this.showNotesDialog = false;
      this.noteText = '';

      if (this.noteTarget.triggerAfterSave === 'reject' && row && column) {
        this.proceedWithRejection(row, column);
      }
    },

    getStyleClassForNormalColumns(data: any): {
        managedPriceClass: string;
        uomClass: string;
      } {
        let managedPriceClass = '';
        let uomClass = '';

        const needsApproval = data?.needs_approval;
        const approvalStatus = data?.approval_status;
        const uomNeedsApproval = data?.uom_needs_approval;
        const uomApprovalStatus = data?.uom_approval_status;

        // UOM logic
        if (uomNeedsApproval && (data?.managed_unit || data?.managed_unit === 0)) {
          uomClass = this.colorOrange;
          if (uomApprovalStatus) {
            uomClass =
              uomApprovalStatus === approvalInfoStatus.approved
                ? this.colorSucess
                : this.colorError;
          }
        } else if (uomApprovalStatus) {
          uomClass =
            uomApprovalStatus === approvalInfoStatus.approved
              ? this.colorSucess
              : this.colorError;
        }

        // Managed Price logic — mirror the UOM guard above: only require
        // approval when a managed price actually exists. A NEW item has an empty
        // managed_price in approval_info that the table fills from the document
        // data, so there is nothing to compare/approve → no approval action.
        if (needsApproval && (data?.managed_price || data?.managed_price === 0)) {
          managedPriceClass = this.colorOrange;
          if (approvalStatus) {
            managedPriceClass =
              approvalStatus === approvalInfoStatus.approved
                ? this.colorSucess
                : this.colorError;
          }
        } else if (approvalStatus) {
          managedPriceClass =
            approvalStatus === approvalInfoStatus.approved
              ? this.colorSucess
              : this.colorError;
        }

        return { managedPriceClass, uomClass };
      },

    
    approveOrRecject(columnName: string, status: string, originalName: string) {

      if (!this.checkForApprovalpermission(originalName)) {
        notify.error(this.$t('NOT_AUTHORIZED_TO_APPROVE'));
        return;
      }
      const colUnitPrice = 'unit_price';
      const colUnit = 'unit';
      const rowsToReject: any[] = [];

      for (let row of this.tableRows) {
        const quoteEntry = (this.record.quote_approval_data || []).find(
          (entry: any) => entry.table_line_id === row.row_id
        );
        if (
          !quoteEntry?.approval_info?.needs_approval &&
          (!quoteEntry?.approval_info?.approval_status || quoteEntry?.approval_info?.approval_status === 'pending')
        ) {
          continue; // ✅ Skip only if nothing has been approved/rejected yet
        }
        // if (
        //   !quoteEntry?.approval_info?.uom_needs_approval &&
        //   (!quoteEntry?.approval_info?.uom_approval_status || quoteEntry?.approval_info?.uom_approval_status === 'pending')
        // ) {
        //   continue; // ✅ Skip only if nothing has been approved/rejected yet
        // }

        for (let [index, column] of Object.entries(row)) {
          if (
            columnName === index &&
            (column as any).class.startsWith('no-left-border')
          ) {
            if (status === this.approvalInfoStatus.rejected && colUnit === columnName){
              this.proceedWithRejection(row, columnName);
            }
            if (status === this.approvalInfoStatus.rejected) {
              rowsToReject.push({ row, quoteEntry });
            } else if (status === this.approvalInfoStatus.approved) {
              this.proceedWithApproval(row, columnName);
            }  else {
              this.restStatus(row, columnName);
            }
          }
        }
      }

      // ✅ Handle rejection: Show popup if rowsToReject is not empty
      if (status === this.approvalInfoStatus.rejected && rowsToReject.length > 0 && colUnitPrice === columnName) {
        this.bulkRejectTarget = {
          rows: rowsToReject,
          column: columnName,
        };
        this.noteText = '';
        this.showNotesDialog = true;
      }
    },

    proceedWithApprovalWrapper(
      rowInfo: any,
      columnName: string,
      originalName: string
    ) {
      // check for user permistion
      if (!this.checkForApprovalpermission(originalName)) {
        notify.error(
          this.$t('NOT_AUTHORIZED_TO_APPROVE')
        );
        return;
      }
      this.proceedWithApproval(rowInfo, columnName);
    },

    proceedWithApproval(rowInfo: any, columnName: string) {
      this.handleApprovalInfo(approvalInfoStatus.approved, columnName, rowInfo);
      const poPairColumnName = rowInfo[columnName].po_pair_name;
      const pair_name = 'managed_price'
      if(poPairColumnName === pair_name){
        this.updateMatrixLookup(approvalInfoStatus.approved, rowInfo);
      }
      rowInfo[columnName].class = 'no-left-border-sucess';
      rowInfo[poPairColumnName].class = 'no-right-border-sucess';
      this.handleRowApprovalStatus(rowInfo);
    },
    updateNotifyButtonsVisibility() {
      const buttons = document.querySelectorAll('.notify_requisitioner');

      let hasRejected = false;

      for (let row of this.tableRows) {
        const quoteEntry = (this.record.quote_approval_data || []).find(
          (entry: any) => entry.table_line_id === row.row_id
        );

        if (quoteEntry?.approval_info?.approval_status === 'rejected' || 
            quoteEntry?.approval_info?.uom_approval_status === 'rejected') {
          hasRejected = true;
          break;
        }
      }

      buttons.forEach(btn => {
        (btn as HTMLElement).style.display = hasRejected ? 'inline-block' : 'none';
      });
    },
    handleRowApprovalStatus(rowInfo: any) {
        let approvalNeeded = false;
        for (const [key, item] of Object.entries(rowInfo as Record<string, any>)) {
          if (item && typeof item === 'object' && 'class' in item && item.class && /orange|success|error$/.test(item.class)) {
            approvalNeeded = true;
            break;
          }
        }
        
        // After processing rowInfo, update buttons visibility
        this.updateNotifyButtonsVisibility();

        this.prepareTableErrors();
    },
    proceedWithRejectionWrapper(rowInfo: any, columnName: string, originalName: string) {
      const quoteEntry = (this.record.quote_approval_data || []).find(
        (entry: any) => entry.table_line_id === rowInfo.row_id
      );
      const poPairColumnName = rowInfo[columnName].po_pair_name;
      const pair_name = 'managed_price';
      const currentNote = quoteEntry?.approval_info?.notes?.trim();

      if (!currentNote && poPairColumnName === pair_name) {
        // 📝 Open note dialog and defer rejection
        this.openNotesDialog({
          type: 'cell',
          column: columnName,
          row: rowInfo,
          triggerAfterSave: 'reject',
          originalName
        });
        return;
      }

      // ✅ Note exists, proceed with rejection
      this.proceedWithRejection(rowInfo, columnName);
      
    },

    proceedWithRejection(rowInfo: any, columnName: string) {
      const quoteEntry = (this.record.quote_approval_data || []).find(
        (entry: any) => entry.table_line_id === rowInfo.row_id
      );
      const poPairColumnName = rowInfo[columnName].po_pair_name;
      const pair_name = 'managed_price';

      if (quoteEntry && quoteEntry.approval_info && poPairColumnName === pair_name) {
        // ✅ If no note exists, show popup first
        if (!quoteEntry.approval_info.notes) {
          this.noteTarget = {
            type: 'cell',
            column: columnName,
            row: rowInfo,
            triggerAfterSave: null,
            originalName: null
          };
          this.noteText = '';
          this.showNotesDialog = true;
          return; // 🛑 Stop here — wait for user to submit note
        }
      }

      // ✅ If note already exists, proceed normally
      this.handleApprovalInfo(this.approvalInfoStatus.rejected, columnName, rowInfo);

      
      rowInfo[columnName].class = 'no-left-border-error';
      rowInfo[poPairColumnName].class = 'no-right-border-error';

      this.handleRowApprovalStatus(rowInfo);
      if(poPairColumnName === pair_name){
        this.updateMatrixLookup(approvalInfoStatus.rejected, rowInfo);
      }
    },

    restStatusWrapper(rowInfo: any, columnName: string, originalName: string) {
      // check for user permistion
      if (!this.checkForApprovalpermission(originalName)) {
        notify.error(
          this.$t('NOT_AUTHORIZED_TO_APPROVE')
        );
        return;
      }
      this.restStatus(rowInfo, columnName);
    },

    restStatus(rowInfo: any, columnName: string) {
      this.handleApprovalInfo(approvalInfoStatus.pending, columnName, rowInfo);
      const poPairColumnName = rowInfo[columnName].po_pair_name;
      const colUnit = 'unit';
      const colUnitPrice = 'unit_price';

      // ✅ Reset class styles
      rowInfo[columnName].class = 'no-left-border-orange';
      rowInfo[poPairColumnName].class = 'no-right-border-orange';

      // ✅ Reset actual approval info object
      const quoteEntry = (this.record.quote_approval_data || []).find(
        (entry: any) => entry.table_line_id === rowInfo.row_id
      );

      if (quoteEntry && quoteEntry.approval_info && columnName === colUnitPrice) {
        quoteEntry.approval_info.needs_approval = true;
        quoteEntry.approval_info.approval_status = '';
        quoteEntry.approval_info.notes = '';
      }

      if (quoteEntry && quoteEntry.approval_info && columnName === colUnit) {
        quoteEntry.approval_info.uom_needs_approval = true;
        quoteEntry.approval_info.uom_approval_status = '';
      }

      this.handleRowApprovalStatus(rowInfo);
    },

    handleApprovalInfo(status: string, columnName: string, rowInfo: any) {
      const tableLineId = rowInfo.row_id;
      const colUnitPrice = 'unit_price';
      const colUnit = 'unit';
      const quoteRecord = (this.record.quote_approval_data || []).find(
        (entry: any) => entry.table_line_id === tableLineId
      );

      if (quoteRecord && quoteRecord.approval_info && columnName === colUnitPrice) {
        quoteRecord.approval_info.approval_status = status;
        quoteRecord.approval_info.needs_approval = false;
      }
      if (quoteRecord && quoteRecord.approval_info && columnName === colUnit) {
        quoteRecord.approval_info.uom_approval_status = status;
        quoteRecord.approval_info.uom_needs_approval = false;
      }
      // ✅ Clear notes if it's being approved
      if (status === this.approvalInfoStatus.approved && colUnitPrice === columnName) {
        quoteRecord.approval_info.notes = '';
        quoteRecord.approval_info.last_price_paid = rowInfo.unit_price.value;
        quoteRecord.approval_info.price_to_export = rowInfo.unit_price.value;
      } else if (status === this.approvalInfoStatus.rejected ) {
        quoteRecord.approval_info.last_price_paid = rowInfo.managed_price.value;
        quoteRecord.approval_info.price_to_export = rowInfo.managed_price.value;
      }

      if (status === this.approvalInfoStatus.approved && colUnit === columnName) {
        quoteRecord.approval_info.uom_to_export = rowInfo.unit.value;
      } else if (status === this.approvalInfoStatus.rejected ) {
        quoteRecord.approval_info.uom_to_export = rowInfo.managed_unit.value;
      }
    },
    async fetchMasterDataForSupplierItems(tableRows: any) {

      const data = {} as dynamicObj;
      data['data_type'] = 'supplier_item_price';
      data['skip'] = 0;
      data['limit'] = 100;

      let filter_json = {
        'match_all' : false,
        'filters' : [] as Array<{field: string, operator: string, value: string}>
      };

      for (const row of tableRows) {
        filter_json.filters.push({ 'field': 'supplier_item_key', 'operator': 'smart', 'value': this.getLineTableValue(row,'SUPPLIER_ITEM_KEY') });
      }

       const response = await masterDataApiService.getData_V2(data, JSON.stringify(filter_json));

       if (response.success == false) {
         throw response;
       }

       this.supplierPriceMasterData = response.data.reduce((acc: any, item: any) => {
         acc[item.supplier_item_key] = item;
          
         return acc;
       }, {});
     },
     prepareTableErrors() {
      this.quotesTableIdsNeedUserAction = [];
      
      for (let row of this.tableRows) {

        // if(!this.supplierPriceMasterData.hasOwnProperty(row.supplier_item_key)) {
        //   this.quotesTableIdsNeedUserAction.push(row.row_id);
        //   continue;
        // }

        for (const [key, value] of Object.entries(row)) {
          const item = value as any;
          if(item && item.class && item.class.includes('border-orange')) {
            this.quotesTableIdsNeedUserAction.push(row.row_id);
            break;
          }
        }
      }
    },
    async bulkAdd() {
       try {

        const payloadList = [] as any[];
        const validationErrors: string[] = [];

        for(let row of this.tableRows) {

          if(this.supplierPriceMasterData[row.supplier_item_key]) {
            continue;
          }

          this.preapreFormData(row, false);

          // Validate each row's form data
          const validation = this.validateFormData(this.formData);
          if (!validation.isValid) {
            
            // const rowKey = String(row.supplier_item_key || 'Unknown');
            // validationErrors.push(`Row ${rowKey}: ${validation.error}`);

            validationErrors.push(validation.error);
            continue;
          }

          const payload = JSON.parse(JSON.stringify(this.formData)) ;
          payload['last_price_paid_last_updated'] = new Date().toISOString();
          payloadList.push(payload);
        }

        // Show validation errors if any
        if (validationErrors.length > 0) {
          notify.error(`Validation failed:\n${validationErrors.join('\n')}`);
          return;
        }

        // Check if there are any valid payloads to process
        if (payloadList.length === 0) {
          notify.error('No valid items to add');
          return;
        }

        //Using Bulk Update Endpoint here as it will update the provided fields only and not remove the dates
        const response = await masterDataApiService.updateBulkRecord('supplier_item_price', payloadList);

        if (!response || response.success !== true) {
          throw response;
        }

        // Add newly created items to supplierPriceMasterData
        for (const payload of payloadList) {
          const supplier_item_key = payload.supplier_item_key as string;
          this.supplierPriceMasterData[supplier_item_key] = payload;
        }

        // Refresh the entire table
        this.prepareTableData();

        notify.success('Updated Record');
        // Save document to persist changes
        this.saveDocument(this.record.doc_id);
      } catch (err: any) {
        const msg = ApiExceptions.getErrorMessage(err);
        notify.error(msg);
        logError(err);
      }
    },
  },
  setup() {

    const master_data_lookup_store = useMasterDataLookupStore();
    const { updateRow } = master_data_lookup_store;
    
    const doc_store = useDocumentStore();
    const { record, quotesTableIdsNeedUserAction} = storeToRefs(doc_store);
    const { checkForApprovalpermission, saveDocument } = doc_store;

    const form_builder_store = useFormBuilderStore();
    const { isFormBuilderMode } = storeToRefs(form_builder_store);
    const auth_token_store = useAuthTokenStore();
    const { isAdmin } = auth_token_store;

    return {
      isAdmin,
      updateRow,
      checkForApprovalpermission,
      saveDocument,
      record,
      isFormBuilderMode,
      quotesTableIdsNeedUserAction,
      approvalNeededColumns: ref(new Set()),
    };
  },
});
</script>

